SELECT r.recipe_id, r.title, r.summary, r.thumbnail_url, r.difficulty_cd, r.cook_time_min, r.cuisine_style_cd, r.category, r.view_cnt, r.like_cnt, r.created_date, r.owner_user_id, u.user_nickname, u.user_profile_image_url, CASE WHEN EXISTS ( SELECT 1 FROM tb_recipe_like l WHERE l.recipe_id = r.recipe_id AND l.user_id = #{loginUserId} ) THEN 1 ELSE 0 END AS liked_by_me FROM tb_recipe r JOIN tb_user u ON u.user_id = r.owner_user_id WHERE r.is_public = 'Y' AND r.is_deleted = 'N'
AND ( LOWER(r.title) LIKE '%' || LOWER(#{search}) || '%' OR LOWER(r.summary) LIKE '%' || LOWER(#{search}) || '%' )
AND r.cuisine_style_cd = #{cuisineStyleCd}
AND r.difficulty_cd = #{difficultyCd}
AND r.cook_time_min <= #{maxCookTimeMin}
ORDER BY r.like_cnt DESC, r.view_cnt DESC, r.created_date DESC
ORDER BY r.created_date DESC
OFFSET #{offset} ROWS FETCH NEXT #{limit} ROWS ONLY

SELECT COUNT(*)
FROM tb_recipe r
WHERE r.is_public = 'Y'
AND r.is_deleted = 'N'

    AND (
    LOWER(r.title) LIKE '%' || LOWER(#{search}) || '%'
    OR LOWER(r.summary) LIKE '%' || LOWER(#{search}) || '%'
    )


    AND r.cuisine_style_cd = #{cuisineStyleCd}


    AND r.difficulty_cd = #{difficultyCd}


    AND r.cook_time_min <= #{maxCookTimeMin}
